package dev.koikaster.mite;
import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;import com.google.gson.*;
import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.item.enchantment.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.storage.loot.*;import net.minecraft.world.level.storage.loot.parameters.LootContextParams;import net.minecraftforge.registries.ForgeRegistries;
/** Original item dispatch and apr fallback facts; no global material/plant guesses. */
public final class SourceSkillWorld1820 {
 private static final Set<Integer> FARMING=new HashSet<>(),ORES=new HashSet<>();private static final Set<String> ADAPTED=new HashSet<>();
 static {try(var in=SourceSkillWorld1820.class.getResourceAsStream("/data/mite_reforged/original_skill_world1820.json")){if(in==null)throw new IOException("Missing source skill world facts");var root=JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();for(var x:root.getAsJsonArray("farming_item_ids"))FARMING.add(x.getAsInt());for(var x:root.getAsJsonArray("apr_ore_ids"))ORES.add(x.getAsInt());ADAPTED.addAll(root.getAsJsonObject("adapted_farming_items").keySet());}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 public static boolean planting(UseOnContext context){var player=context.getPlayer();if(player==null||!SourceSkills1685.enabled(player.level())||SourceSkills1685.has(player,SourceSkillRules1685.FARMING))return true;var stack=context.getItemInHand();var original=SourceSkillFacts1710.original(stack);var key=ForgeRegistries.ITEMS.getKey(stack.getItem());return !(original!=null&&FARMING.contains(original.id())||key!=null&&ADAPTED.contains(key.toString()));}
 public static boolean enchanting(Player player){return player!=null&&(!SourceSkills1685.enabled(player.level())||SourceSkills1685.has(player,SourceSkillRules1685.ENCHANTING));}
 public static void oreLoot(List<ItemStack> loot,LootContext context,BlockState state){if(!(context.getParamOrNull(LootContextParams.THIS_ENTITY) instanceof Player player)||!SourceSkills1685.enabled(player.level())||SourceSkills1685.has(player,SourceSkillRules1685.MINING)||context.hasParam(LootContextParams.EXPLOSION_RADIUS))return;var tool=context.getParamOrNull(LootContextParams.TOOL);if(tool!=null&&EnchantmentHelper.getItemEnchantmentLevel(Enchantments.SILK_TOUCH,tool)>0)return;var item=new ItemStack(state.getBlock());var original=SourceSkillFacts1710.original(item);if(original!=null&&ORES.contains(original.id())){loot.clear();loot.add(item);}}
 private SourceSkillWorld1820(){}
}
